INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 2, 'theory', 'Quiz: scaling and load balancing');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 2, 0, 'What is the most significant limitation of vertical scaling?', '["The program has to be rewritten", "There is a limit to a single machine''s power, and it remains a single point of failure", "You cannot use a database", "A load balancer is required"]', 1, 'Vertical scaling hits a ceiling and gives no redundancy; on the other hand, the program doesn''t need to change.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 2, 1, 'What does "a stateless application" mean?', '["The application doesn''t write logs", "Any instance can handle any request: sessions and data live in external stores", "The application doesn''t use memory", "The application works without a database"]', 1, 'Stateless means the server remembers nothing locally between requests, and instances are interchangeable.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 2, 2, 'Which session storage method frees the server from pinning a user to a machine and requires no store?', '["Sticky sessions", "A session in server memory", "A signed token on the client", "A cookie with the password"]', 2, 'A signed token is verified by its signature; the drawback is that it is hard to revoke, so its lifetime is short.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 2, 3, 'What can an L7 balancer do that an L4 one cannot?', '["Forward bytes", "Route by HTTP path and headers", "Check server availability", "Distribute requests round robin"]', 1, 'L7 understands the application protocol; L4 sees only addresses and ports, but is faster and cheaper.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 2, 4, 'A service needs 1000 requests per second, and one server handles 450. How many servers are needed with N+1 headroom at no more than 100% utilization?', '["2", "3", "4", "5"]', 2, 'For 1000 you need three servers (1350); with one spare, four: after losing any one, the remaining three carry the peak.');
